const body = $input.first().json.body || {};
const msg  = body.message || {};

if (msg.type !== 'end-of-call-report') {
  return [];
}

const outputs =
  msg.artifact?.structuredOutputs || {};

const booking = Object.values(outputs).find(
  o => o.name === 'booking info'
);

const sd = booking?.result || {};

const callerPhone =
  msg.call?.customer?.number || '';

const whatsappRaw =
  sd.whatsappNumber || callerPhone || '';

const toE164 = (raw) => {
  if (!raw) return '';
  const d = String(raw).replace(/\D/g, '');

  if (d.length === 10) return '+1' + d;
  if (d.length === 11 && d.startsWith('1')) return '+' + d;

  return '+' + d;
};

const callerE164   = toE164(callerPhone);
const whatsappE164 = toE164(whatsappRaw);

const customerName =
  sd.customerName || 'Guest';

const orderType =
  (sd.orderType || 'pickup').toLowerCase();

const rawItems =
  Array.isArray(sd.items) ? sd.items : [];

const subtotalRaw =
  parseFloat(sd.subtotal || 0);

const TAX_RATE = 0.08875;

const tax =
  parseFloat((subtotalRaw * TAX_RATE).toFixed(2));

const total =
  parseFloat((subtotalRaw + tax).toFixed(2));

const now  = new Date();
const ymd  = now.toISOString().slice(0,10).replace(/-/g,'');

const rand =
  Math.floor(1000 + Math.random() * 9000);

const orderId =
  `NYPDQ-${ymd}-${rand}`;

const timestamp =
  now.toLocaleString('en-US', {
    timeZone: 'America/New_York',
    dateStyle: 'short',
    timeStyle: 'short'
  });

const itemsSheet = rawItems
  .map(i =>
    `${i.qty || 1}x ${i.name} @ $${parseFloat(i.price || 0).toFixed(2)}`
  )
  .join(' | ');

const itemsWA = rawItems
  .map(i => {
    const qty   = i.qty || 1;
    const price = parseFloat(i.price || 0);

    return `• ${qty}x ${i.name} - $${(qty * price).toFixed(2)}`;
  })
  .join('\n');

const orderLine =
  orderType === 'delivery'
    ? 'Delivery order'
    : 'Pickup at 3101 31st Ave, Astoria, Queens';

const whatsappMsg =
`New York Pao de Queijo

Hi ${customerName}!

Thanks for calling us.

Order ID: ${orderId}

Items:
${itemsWA}

${orderLine}

Subtotal: $${subtotalRaw.toFixed(2)}
Tax: $${tax.toFixed(2)}
Total: $${total.toFixed(2)}

Reply YES to confirm your order.`;

return [{
  json: {
    orderId,
    timestamp,
    customerName,
    callerPhone: callerE164,
    whatsappNumber: whatsappE164,
    sameNumber: callerE164 === whatsappE164,
    orderType,
    itemsSheet,
    itemsWA,
    subtotal: '$' + subtotalRaw.toFixed(2),
    tax: '$' + tax.toFixed(2),
    total: '$' + total.toFixed(2),
    totalRaw: total,
    deliveryAddress: '',
    status: 'PENDING_CONFIRMATION',
    whatsappMsg
  }
}];

// ============================================================
// FIXED: Check Customer Exists
// Handles: empty callerPhone, no Supabase results, skip flag
// ============================================================

const parsed   = $('Parse Vapi Payload').item.json;
const response = $input.first().json;

// ── If Parse node flagged this as skip, pass it through ──────
if (parsed.skip === true) {
  return { skip: true, reason: parsed.reason };
}

// ── Supabase returns an array ─────────────────────────────────
// If callerPhone was empty, the query still runs but returns []
// If Supabase had an error, it may return an error object
let customers = [];

if (Array.isArray(response)) {
  customers = response;
} else if (response?.error) {
  // Supabase returned an error — treat as new customer
  console.log('Supabase error on Find Customer:', JSON.stringify(response.error));
  customers = [];
} else if (response && typeof response === 'object') {
  // Single object returned — wrap it
  customers = [response];
}

const existing = customers.length > 0 ? customers[0] : null;

return {
  ...parsed,
  isExistingCustomer: existing !== null,
  existingCustomerId: existing?.id || null,
  existingCustomerData: existing || null
};

// Merge: get customerId from whichever branch ran
const parsed = $('Check Customer Exists').item.json;

// The previous node is either Update or Create — both return representation array
const prevResult = $input.first().json;
const resultArr  = Array.isArray(prevResult) ? prevResult : [prevResult];
const customer   = resultArr[0] || {};

const customerId = customer.id || parsed.existingCustomerId || null;

return {
  ...parsed,
  customerId
};

// Extract order DB id + pass everything forward for order items loop
const merged   = $('Merge Customer ID').item.json;
const prevResult = $input.first().json;
const resultArr  = Array.isArray(prevResult) ? prevResult : [prevResult];
const order      = resultArr[0] || {};

const orderDbId = order.id || null;

// Build one output item per line-item so SplitInBatches can loop them
const items = merged.rawItems || [];

if (items.length === 0) {
  // No items — still pass something forward
  return [{
    ...merged,
    orderDbId,
    order_id:     orderDbId,
    menu_item_id: null,
    name:         'Unknown',
    quantity:     1,
    price:        0,
    notes:        ''
  }];
}

return items.map(item => ({
  ...merged,
  orderDbId,
  order_id:     orderDbId,
  menu_item_id: item.menu_item_id || null,
  name:         item.name,
  quantity:     item.qty || 1,
  price:        parseFloat(item.price || 0),
  notes:        item.notes || ''
}));

// After all items are inserted, pull the first item's full data
// (all items share the same order-level fields)
const allItems = $input.all();
const first    = allItems[0].json;

// Re-merge everything we need for the WhatsApp send
const merged = $('Prep Order Items').first().json;

return {
  whatsappNumber: merged.whatsappNumber,
  whatsappMsg:    merged.whatsappMsg,
  orderId:        merged.orderId,
  orderDbId:      merged.orderDbId,
  customerName:   merged.customerName,
  total:          merged.total
};

// ============================================================
// PARSE VAPI PAYLOAD — FINAL CORRECT VERSION
// 
// CONFIRMED from actual webhook payload:
// Structured data is at:
//   body.message.artifact.structuredOutputs["SCHEMA_ID"].result
//
// NOT at:
//   message.call.analysis.structuredData   ❌
//   message.artifact.structuredData        ❌
//
// The schema named "booking info" has ID: 93198513-5ba8-4b6c-96b2-cd5f38a25c0d
// ============================================================

const body = $input.first().json?.body || $input.first().json;
const msg  = body?.message || {};

// ── Only process end-of-call-report ──────────────────────────
if (msg.type !== 'end-of-call-report') {
  return { skip: true, reason: `Ignoring: ${msg.type}` };
}

// ── Pull structuredOutputs from artifact ─────────────────────
// Real path confirmed: message.artifact.structuredOutputs
const structuredOutputs = msg?.artifact?.structuredOutputs || {};

// Find the "booking info" result — search by name, not hardcoded ID
// (in case the schema ID ever changes)
let sd = {};

const outputKeys = Object.keys(structuredOutputs);
for (const key of outputKeys) {
  const entry = structuredOutputs[key];
  // Match by name "booking info" OR just grab any entry that has items/orderType
  if (
    entry?.name === 'booking info' ||
    (entry?.result?.items && entry?.result?.orderType)
  ) {
    sd = entry.result || {};
    break;
  }
}

// Fallback: if no named match, try to merge all results that look like order data
if (Object.keys(sd).length === 0) {
  for (const key of outputKeys) {
    const result = structuredOutputs[key]?.result;
    if (result && typeof result === 'object') {
      Object.assign(sd, result);
    }
  }
}

// ── Extract fields ────────────────────────────────────────────
const customerName    = sd?.customerName    || 'Guest';
const whatsappRaw     = sd?.whatsappNumber  || '';
const orderType       = (sd?.orderType      || 'pickup').toLowerCase();
const rawItems        = Array.isArray(sd?.items) ? sd.items : [];
const subtotalRaw     = parseFloat(sd?.subtotal) || 0;
const deliveryAddress = sd?.deliveryAddress || '';
const sameNumber      = sd?.sameNumber === true || sd?.sameNumber === 'true';

// Caller phone — empty for webCall (browser), real number for phone calls
const callerPhone = msg?.call?.customer?.number || '';

// ── Normalize phone to E.164 ──────────────────────────────────
const toE164 = (raw) => {
  if (!raw) return '';
  const d = String(raw).replace(/\D/g, '');
  if (d.length === 10) return '+1' + d;
  if (d.length === 11 && d[0] === '1') return '+' + d;
  if (d.length >= 7) return '+' + d;
  return '';
};

const callerE164   = toE164(callerPhone);
const whatsappE164 = toE164(whatsappRaw);

// ── Money ─────────────────────────────────────────────────────
const TAX_RATE = 0.18; // 18% GST — change to 0.08875 for NY/USD
const tax      = parseFloat((subtotalRaw * TAX_RATE).toFixed(2));
const total    = parseFloat((subtotalRaw + tax).toFixed(2));

// ── Order ID ──────────────────────────────────────────────────
const now     = new Date();
const ymd     = now.toISOString().slice(0,10).replace(/-/g,'');
const rand    = Math.floor(1000 + Math.random() * 9000);
const orderId = `ORD-${ymd}-${rand}`;

const timestamp        = now.toISOString();
const timestampDisplay = now.toLocaleString('en-IN', {
  timeZone:  'Asia/Kolkata',
  dateStyle: 'short',
  timeStyle: 'short'
});

// ── Format items ──────────────────────────────────────────────
const itemsSheet = rawItems
  .map(i => `${i.qty || 1}x ${i.name} @ ₹${parseFloat(i.price || 0).toFixed(0)}`)
  .join(' | ');

const itemsWA = rawItems.length > 0
  ? rawItems.map(i => {
      const qty   = i.qty   || 1;
      const price = parseFloat(i.price || 0);
      return `  • ${qty}x ${i.name} — ₹${(qty * price).toFixed(0)}`;
    }).join('\n')
  : '  (no items)';

// ── WhatsApp message ──────────────────────────────────────────
const orderLine = orderType === 'delivery'
  ? `🚗 *Delivery to:* ${deliveryAddress || 'TBC'}`
  : '🏪 *Pickup* — collect at the restaurant';

const ctaLine = orderType === 'delivery'
  ? 'Your delivery will be on its way once payment clears!'
  : 'Your order will be ready in 15–20 mins after payment!';

const whatsappMsg =
`🍽 *Order Confirmed!*

Hi ${customerName}! Here's your order summary:

📋 *Order ID:* ${orderId}

🛒 *Items:*
${itemsWA}

${orderLine}

━━━━━━━━━━━━━━━
💰 Subtotal:  ₹${subtotalRaw.toFixed(0)}
🏛 Tax (18%): ₹${tax.toFixed(0)}
✅ *Total:     ₹${total.toFixed(0)}*
━━━━━━━━━━━━━━━

👇 *Tap to pay:*
PAYMENT_LINK_PLACEHOLDER

⏱ Link expires in 30 mins.
${ctaLine}

_Questions? Call: (718) 555-9001_`;

// ── Debug log ─────────────────────────────────────────────────
console.log('=== PARSE RESULT ===');
console.log('Structured outputs found:', outputKeys.length);
console.log('SD keys extracted:', Object.keys(sd).join(', '));
console.log('customerName:', customerName);
console.log('whatsappNumber:', whatsappE164);
console.log('items:', rawItems.length);
console.log('subtotal:', subtotalRaw);
console.log('===================');

return {
  skip: false,
  orderId,
  timestamp,
  timestampDisplay,
  callId: msg?.call?.id || '',

  customerName,
  callerPhone:    callerE164,
  whatsappNumber: whatsappE164,
  sameNumber,

  orderType,
  deliveryAddress,
  itemsSheet,
  itemsWA,
  rawItems,

  subtotal:        subtotalRaw,
  tax,
  total,
  subtotalDisplay: `₹${subtotalRaw.toFixed(0)}`,
  taxDisplay:      `₹${tax.toFixed(0)}`,
  totalDisplay:    `₹${total.toFixed(0)}`,

  status:      'PENDING_PAYMENT',
  whatsappMsg
};

// Vapi sends tool call body like:
// { "items": [ { "name": "Classic Lemonade", "qty": 1 }, ... ] }
//
// Also handles nested formats Vapi sometimes uses:
// { "message": { "toolCallList": [{ "function": { "arguments": { "items": [...] } } }] } }

const raw = $input.first().json;

// n8n Webhook nodes nest the incoming payload inside a "body" property
const payload = raw?.body || raw;

// Try direct payload first
let items = payload?.items || [];

// Try nested Vapi tool call format
if (!items.length) {
  const toolCall = payload?.message?.toolCallList?.[0];
  const args = toolCall?.function?.arguments;

  if (args?.items) {
    items = args.items;
  } else if (typeof args === 'string') {
    try { 
      items = JSON.parse(args)?.items || []; 
    } catch(e) {
      console.error("Failed to parse stringified arguments");
    }
  }
}

// Ensure items is a proper array
if (!Array.isArray(items)) items = [];

console.log('Items received for pricing:', JSON.stringify(items));

// Output one item per row for the Supabase lookup loop
return items.map(i => ({
  name: String(i.name || '').trim(),
  qty:  Number(i.qty || 1)
}));

// Retrieve ALL items that originally came out of the "Parse Items" node
const originalItems = $('Parse Items').all();

// Retrieve ALL responses that came back from the Supabase lookup node
const supabaseResponses = $('Lookup Price — Supabase').all();

// Reach back to the original Webhook payload to get the unique Vapi toolCallId
const rawWebhook = $('Webhook — Calculate Total').first().json;
const payload = rawWebhook?.body || rawWebhook;
const toolCallId = payload?.message?.toolCallList?.[0]?.id || "unknown_id";

let subtotal = 0;
const formatted = [];
const missing = [];

// Loop through what the user actually ordered
for (let i = 0; i < originalItems.length; i++) {
  const orderedItem = originalItems[i].json;

  // Find the corresponding Supabase response for this specific iteration loop
  const dbResponse = supabaseResponses[i]?.json;
  const dbRow = Array.isArray(dbResponse) ? dbResponse[0] : dbResponse;

  const qty = Number(orderedItem.qty || 1);
  const name = orderedItem.name || 'Unknown';

  if (!dbRow || !dbRow.price) {
    missing.push(name);
    continue;
  }

  const price = Number(dbRow.price);
  const lineTotal = qty * price;
  subtotal += lineTotal;

  formatted.push({
    name: dbRow.name,
    qty,
    price,
    lineTotal
  });
}

// NY tax 8.875%
const TAX_RATE = 0.08875;
const tax = parseFloat((subtotal * TAX_RATE).toFixed(2));
const total = parseFloat((subtotal + tax).toFixed(2));

const spokenTotal = `Your total comes to $${total.toFixed(2)} including tax.`;

// Create the raw data object
const receiptData = {
  items: formatted,
  subtotal: parseFloat(subtotal.toFixed(2)),
  tax,
  total,
  spokenTotal,
  missingItems: missing,
  success: missing.length === 0
};

// Wrap the final response exactly how Vapi expects it
return [{
  json: {
    results: [
      {
        toolCallId: toolCallId,
        result: receiptData
      }
    ]
  }
}];

