const parsed = $('Build Menu Query').first().json;
const menuRows = $input.all().map(i => i.json);

const normalize = (str = '') =>
  String(str)
    .toLowerCase()
    .trim()
    .replace(/\s+/g, ' ');

// 1. Map your database menu items using the exact database integers
const menuMap = {};
for (const row of menuRows) {
  menuMap[normalize(row.name)] = {
    id: row.id,
    name: row.name,
    description: row.description || 'Freshly made item',
    category: row.category || 'Main',
    price: parseInt(row.price || 0) // e.g., 557, 528 exactly
  };
}

// 2. Re-extract item matches directly from the query filter
let itemsToProcess = [];
const filterString = parsed.menuFetchUrl || parsed.supabaseQueryFilter || '';
const matches = filterString.match(/name\.ilike\.([^,)]+)/g);

if (matches) {
  itemsToProcess = matches.map(m => {
    let rawName = m.replace('name.ilike.', '');
    rawName = decodeURIComponent(rawName).trim();
    return {
      name: rawName,
      qty: 1
    };
  });
}

const enrichedItems = [];
let subtotalCents = 0;

// 3. Process matched menu items and calculate totals
for (const item of itemsToProcess) {
  const qty = parseInt(item.qty || 1);
  const normalized = normalize(item.name);
  const found = menuMap[normalized];

  if (!found) {
    enrichedItems.push({
      name: item.name,
      qty,
      price: 0,
      description: '',
      category: '',
      menu_item_id: null,
      found: false,
      lineTotal: 0
    });
    continue;
  }

  const lineTotalCents = qty * found.price;
  subtotalCents += lineTotalCents;

  enrichedItems.push({
    name: found.name,
    qty,
    price: found.price,
    description: found.description,
    category: found.category,
    menu_item_id: found.id,
    found: true,
    lineTotal: lineTotalCents
  });
}

// NO ROUNDING AT ALL: Use pure integer math for tax and totals
const TAX_RATE = 0.08875;
const taxCents = Math.floor(subtotalCents * TAX_RATE); // Direct drop-down truncation instead of rounding up
const totalCents = subtotalCents + taxCents;

// Filter out items that weren't found from the customer message strings
const validItems = enrichedItems.filter(i => i.found);

// A clean string injector that adds a dot before the last two numbers without changing/rounding values
const formatCentsString = (cents) => {
  const str = String(cents);
  if (str.length <= 2) return '0.' + str.padStart(2, '0');
  return str.slice(0, -2) + '.' + str.slice(-2);
};

// 4. Construct a single clean layout string with metadata
const itemsSummary = validItems.length > 0 
  ? validItems.map(i => `• ${i.qty}x ${i.name} [${i.category}] - $${formatCentsString(i.lineTotal)}\n  (${i.description})`).join('\n')
  : '• (No items successfully matched)';

const orderLine = parsed.orderType === 'delivery'
  ? `Delivery to: ${parsed.deliveryAddress || 'TBD'}`
  : `Pickup at 3101 31st Ave, Astoria, Queens`;

const whatsappMsg = `New York Pao de Queijo

Hi ${parsed.customerName || 'Customer'}!

Thanks for calling us.

Order ID: ${parsed.orderId}

Items Ordered:
${itemsSummary}

${orderLine}

Subtotal: $${formatCentsString(subtotalCents)}
Tax: $${formatCentsString(taxCents)}
Total: $${formatCentsString(totalCents)}

Reply YES to confirm your order.`;

// Erase previous broken fields from the upstream payload
const cleanParsed = { ...parsed };
delete cleanParsed.itemsSheet;
delete cleanParsed.itemsWA;

return [
  {
    json: {
      ...cleanParsed,
      rawItems: enrichedItems,
      itemsSummary,
      subtotal: subtotalCents, // Retains raw integer exactness
      tax: taxCents,           // Retains raw integer exactness
      total: totalCents,       // Retains raw integer exactness
      subtotalDisplay: '$' + formatCentsString(subtotalCents),
      taxDisplay: '$' + formatCentsString(taxCents),
      totalDisplay: '$' + formatCentsString(totalCents),
      totalRaw: totalCents,
      whatsappMsg
    }
  }
];

const data = $input.first().json;

// =====================================================
// GET RAW ITEMS
// =====================================================

const rawItems = [];

const itemMatches =
data.itemsSheet.match(/(\d+)x\s([^@]+)/g) || [];

for (const match of itemMatches) {

const cleaned =
match
.replace(/^\d+x\s/, '')
.trim();

rawItems.push(cleaned);
}

// =====================================================
// UNIQUE ITEMS
// =====================================================

const uniqueItems =
[...new Set(rawItems)];

// =====================================================
// BUILD SUPABASE FILTER
// =====================================================

const encoded =
uniqueItems
.map(name =>
`name.ilike.${encodeURIComponent(name)}`
)
.join(',');

// =====================================================
// FINAL URL
// =====================================================

const url =
`https://rvqcajvsnvafzdmdotcw.supabase.co/rest/v1/menu_items` +
`?select=id,name,price` +
`&or=(${encoded})`;

return [{
json: {
...data,
menuFetchUrl: url
}
}];

const body = $input.first().json.body || {};
const msg  = body.message || {};

if (msg.type !== 'end-of-call-report') {
  return [];
}

const outputs =
  msg.artifact?.structuredOutputs || {};

const booking = Object.values(outputs).find(
