  const found = menuMap[normalized];

  if (!found) {
    enrichedItems.push({
      name: item.name,
      qty,
      price: 0,
      description: '',
      category: '',
      menu_item_id: null,
      found: false,
      lineTotal: 0
    });
    continue;
  }

  const lineTotalCents = qty * found.price;
  subtotalCents += lineTotalCents;

  enrichedItems.push({
    name: found.name,
    qty,
    price: found.price,
    description: found.description,
    category: found.category,
    menu_item_id: found.id,
    found: true,
    lineTotal: lineTotalCents
  });
